  ('563141d1-5ace-5c13-aff0-afb58f0c45e8', null, (select id from public.skills where slug = 'read-g10-main-idea-summary'), null, 'hard',
   $q$How does the fourth paragraph shape the central idea?$q$, $q$[{"text":"It shows that the benefit depends on the native ants in particular, which leads to the conclusion that the relationship itself needs protection.","is_correct":true},{"text":"It shows that the hollowbell no longer needs ants, since its seeds can sprout where they fall.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"It shifts the passage's main topic from wildflowers to the spread of invasive insects.","is_correct":false,"misconception_token":"misreads-structure"},{"text":"It proves that invasive ants are more intelligent than native ants because they eat faster.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$It shows that the benefit depends on the native ants in particular, which leads to the conclusion that the relationship itself needs protection.$q$, $q$Where invasive ants replaced native ones, seeds were left exposed and patches shrank, which sets up the final claim that the plant's future "depends on a relationship." The invasive ants are discussed only as they affect the partnership, so the topic does not shift.$q$, 'draft', '9bb116b0-d618-5546-8e82-4d075173c889')
