  ('e4ec3694-c61a-5b36-8258-b26286d63983', null, (select id from public.skills where slug = 'read-g10-main-idea-summary'), null, 'medium',
   $q$How does the example of Imani Castellanos support the central claim?$q$, $q$[{"text":"It shows that students need expensive equipment to do real science outdoors.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"It shows careful observation in a notebook leading a student to ask a question and plan an experiment.","is_correct":true},{"text":"It shows that maple trees grow better on their south side than on their north side.","is_correct":false,"misconception_token":"misses-purpose"},{"text":"It proves that every student who keeps a notebook will design an experiment.","is_correct":false,"misconception_token":"overgeneralization"}]$q$::jsonb, $q$It shows careful observation in a notebook leading a student to ask a question and plan an experiment.$q$, $q$Imani noticed a difference by sketching one tree for weeks and then "designed an experiment to find out why," which illustrates observation as "where science begins." The fact about the tree matters only as an example of what observation reveals.$q$, 'draft', '09532bbe-2025-5fbf-af6d-ed587b3fd74f')
